('TCC','INE887D01016','INE887D01024','{"previous_isin": "INE887D01016", "current_isin": "INE887D01024", "reviewed": true, "observed_on": "2026-10-20", "allow_previous_through": "2026-10-19", "master_sha256": "64bc3997cc8e6d67f77fec2d04e4f74c45d7f7cb712ffd55c0885fb5a56722d8", "quote_sha256": "32b9fb90b9e3d97f94280d268969fd028c9e61eac577f952501511e4c9919e20", "quote_url": "https://www.nseindia.com/api/NextApi/apiClient/GetQuoteApi?functionName=getSymbolData&marketType=N&series=EQ&symbol=TCC", "observed_at": "2026-10-20T13:03:47.579339+05:30"}')), checked AS (
 SELECT count(*)=6 AS complete FROM reviewed r JOIN pms.instruments i
 ON i.nse_symbol=r.symbol AND i.isin=r.previous_isin
)
UPDATE pms.instruments i SET isin=r.current_isin,
 metadata=coalesce(i.metadata,'{}'::jsonb) || jsonb_build_object(
 'reviewed_isin_history',coalesce(i.metadata->'reviewed_isin_history','[]'::jsonb) || jsonb_build_array(r.evidence::jsonb))
FROM reviewed r, checked c WHERE c.complete AND i.nse_symbol=r.symbol AND i.isin=r.previous_isin
RETURNING i.id,i.nse_symbol,i.isin,i.external_security_id;
